import { test, expect } from '@playwright/test';

test.describe('Modal Dialog - Focus Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body>' +
      '<button id="openModal">Open Modal</button>' +
      '<div id="modal" role="dialog" aria-labelledby="modalTitle" style="display:none; position:fixed; top:50%; left:50%; transform:translate(-50%,-50%); background:white; border:1px solid black; padding:20px; z-index:1000;">' +
      '<h2 id="modalTitle">Modal Title</h2>' +
      '<p>Modal content goes here</p>' +
      '<button id="closeModal">Close Modal</button>' +
      '</div>' +
      '<div id="backdrop" style="display:none; position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.5); z-index:999;"></div>' +
      '<script>' +
      'const openBtn = document.getElementById("openModal");' +
      'const closeBtn = document.getElementById("closeModal");' +
      'const modal = document.getElementById("modal");' +
      'const backdrop = document.getElementById("backdrop");' +
      'openBtn.addEventListener("click", () => {' +
      '  modal.style.display = "block";' +
      '  backdrop.style.display = "block";' +
      '  closeBtn.focus();' +
      '});' +
      'closeBtn.addEventListener("click", () => {' +
      '  modal.style.display = "none";' +
      '  backdrop.style.display = "none";' +
      '  openBtn.focus();' +
      '});' +
      'backdrop.addEventListener("click", () => {' +
      '  modal.style.display = "none";' +
      '  backdrop.style.display = "none";' +
      '  openBtn.focus();' +
      '});' +
      '</script>' +
      '</body></html>');
  });

  test('should return focus to trigger button when modal is closed via close button', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const closeButton = page.getByRole('button', { name: 'Close Modal' });

    // Verify initial focus state
    await openButton.focus();
    await expect(openButton).toBeFocused();

    // Open the modal
    await openButton.click();

    // Verify modal is visible and close button has focus
    const modal = page.locator('[role="dialog"]');
    await expect(modal).toBeVisible();
    await expect(closeButton).toBeFocused();

    // Close the modal
    await closeButton.click();

    // Verify modal is hidden and focus returns to trigger button
    await expect(modal).not.toBeVisible();
    await expect(openButton).toBeFocused();
  });

  test('should return focus to trigger button when modal is closed via backdrop click', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const backdrop = page.locator('#backdrop');

    // Open the modal
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[role="dialog"]');
    await expect(modal).toBeVisible();
    await expect(backdrop).toBeVisible();

    // Click on backdrop to close modal
    await backdrop.click();

    // Verify modal is hidden and focus returns to trigger button
    await expect(modal).not.toBeVisible();
    await expect(openButton).toBeFocused();
  });

  test('should maintain focus management through multiple open/close cycles', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const closeButton = page.getByRole('button', { name: 'Close Modal' });
    const modal = page.locator('[role="dialog"]');

    // First cycle
    await openButton.click();
    await expect(modal).toBeVisible();
    await expect(closeButton).toBeFocused();

    await closeButton.click();
    await expect(modal).not.toBeVisible();
    await expect(openButton).toBeFocused();

    // Second cycle
    await openButton.click();
    await expect(modal).toBeVisible();
    await expect(closeButton).toBeFocused();

    await closeButton.click();
    await expect(modal).not.toBeVisible();
    await expect(openButton).toBeFocused();

    // Third cycle
    await openButton.click();
    await expect(modal).toBeVisible();

    await closeButton.click();
    await expect(modal).not.toBeVisible();
    await expect(openButton).toBeFocused();
  });

  test('should trap focus within modal while open and restore on close', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const closeButton = page.getByRole('button', { name: 'Close Modal' });
    const modal = page.locator('[role="dialog"]');

    // Open modal
    await openButton.click();
    await expect(modal).toBeVisible();

    // Verify close button has focus
    await expect(closeButton).toBeFocused();

    // Tab to next focusable element (should cycle within modal)
    await page.keyboard.press('Tab');

    // Close modal using keyboard
    await closeButton.click();

    // Verify focus returns to open button
    await expect(openButton).toBeFocused();
    await expect(modal).not.toBeVisible();
  });

  test('should handle rapid open/close operations correctly', async ({ page }) => {
    const openButton = page.getByRole('button', { name: 'Open Modal' });
    const closeButton = page.getByRole('button', { name: 'Close Modal' });
    const modal = page.locator('[role="dialog"]');

    // Rapid open/close sequence
    for (let i = 0; i < 3; i++) {
      await openButton.click();
      await expect(modal).toBeVisible();
      await closeButton.click();
      await expect(modal).not.toBeVisible();
      await expect(openButton).toBeFocused();
    }
  });
});
